+  let taskId = match[1];
+  try {
+    taskId = decodeURIComponent(taskId);
+  } catch {
+    // Malformed percent-encoding: keep the raw segment.
+  }
+  if (!taskId || taskId === '.' || taskId === '..') return null;
+  return { projectId: project.id, taskId };
