+		assert.equal(calls.length, 2);
+		assert.deepEqual(
+			calls.map((c) => c.seq),
+			[0, 1],
+		);
+		assert.deepEqual(
+			calls[1].events.map((e) => e.type),
+			["run_finished"],
+		);
+	});
